'use client';

import { useEffect, useRef, useState, type ChangeEvent, type ReactNode } from 'react';
import {
  ArrowRight, Bell, BookOpen, CalendarDays, Check, CheckCircle2, ClipboardCheck,
  Clock3, Copy, Dices, Download, ExternalLink, FileText, Grid2X2, Home as HomeIcon,
  LockKeyhole, LogOut, MessageCircle, Palette, Plus, RotateCcw, Save, Search,
  Send, Settings2, ShieldCheck, Trash2, Upload, Users, X,
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';

type Role = 'teacher' | 'family' | 'screen';
type TeacherView = 'home' | 'journal' | 'homework' | 'class' | 'tools' | 'settings';
type FamilyView = 'journal' | 'homework' | 'calendar' | 'me';
type Student = { number: number; name: string };
type Journal = { id: string; date: string; homework: string; bring: string; notice: string; published: boolean; readBy: boolean; reply: string; readByStudents?: number[]; replies?: Record<string, string> };
type Homework = { id: string; subject: string; title: string; due: string; screenReported: number[]; familyDone: number[]; teacherConfirmed: number[] };
type CalendarEvent = { id: string; date: string; title: string; type: '活動' | '考試' | '提醒' };
type AppData = { className: string; inviteCode: string; teacherUsername: string; teacherPassword: string; teacherPasswordHash: string; familyUsername: string; familyPasswordHash: string; students: Student[]; journals: Journal[]; homeworks: Homework[]; events: CalendarEvent[]; linkedChild: number | null; theme: 'coral' | 'blue' | 'mint'; grid: boolean };

const emptyData: AppData = { className: '', inviteCode: '', teacherUsername: '', teacherPassword: '', teacherPasswordHash: '', familyUsername: '', familyPasswordHash: '', students: [], journals: [], homeworks: [], events: [], linkedChild: null, theme: 'coral', grid: true };
const storageKey = 'class-little-notebook-prototype-v5';
const sessionKey = 'class-little-notebook-session-v1';
function getToday() { const now = new Date(); const year = now.getFullYear(); const month = String(now.getMonth() + 1).padStart(2, '0'); const day = String(now.getDate()).padStart(2, '0'); return `${year}-${month}-${day}`; }
const today = getToday();

function cn(...items: Array<string | false | undefined | null>) { return items.filter(Boolean).join(' '); }
function makeId(prefix: string) { return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`; }
async function hashSecret(secret: string) { const bytes = new TextEncoder().encode(secret); const digest = await crypto.subtle.digest('SHA-256', bytes); return Array.from(new Uint8Array(digest)).map((value) => value.toString(16).padStart(2, '0')).join(''); }
function statusLabel(work: Homework, studentNumber?: number) { if (studentNumber && work.teacherConfirmed.includes(studentNumber)) return '教師已確認'; if (studentNumber && (work.screenReported.includes(studentNumber) || work.familyDone.includes(studentNumber))) return '待教師核對'; return '未登記'; }
function journalReadBy(journal: Journal, studentNumber: number) { return journal.readByStudents?.includes(studentNumber) || journal.readBy; }
function journalReply(journal: Journal, studentNumber: number) { return journal.replies?.[String(studentNumber)] || journal.reply; }
function downloadFile(filename: string, content: string, type = 'application/json') { const blob = new Blob([content], { type }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); }
function csvEscape(value: string | number) { return `"${String(value).replaceAll('"', '""')}"`; }
function Pill({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'orange' | 'gray' | 'blue' }) { return <Badge className={cn('simple-pill', `simple-pill-${tone}`)}>{children}</Badge>; }

function Logo() { return <div className="simple-logo"><span>小</span><div><strong>班級小本本</strong><small>班級聯絡簿</small></div></div>; }

function Login({ data, updateData, onEnter }: { data: AppData; updateData: (next: AppData) => void; onEnter: (role: 'teacher' | 'family', remember: boolean) => void }) {
  const [role, setRole] = useState<'teacher' | 'family'>('teacher');
  const [authMode, setAuthMode] = useState<'invite' | 'account'>('invite');
  const [username, setUsername] = useState(data.teacherUsername || 'teacher');
  const [familyUsername, setFamilyUsername] = useState(data.familyUsername || '');
  const [secret, setSecret] = useState('');
  const [invite, setInvite] = useState('');
  const [remember, setRemember] = useState(true);
  const [error, setError] = useState('');
  const firstTeacherLogin = !data.teacherPassword && !data.teacherPasswordHash;
  const familyAccountReady = Boolean(data.familyUsername && data.familyPasswordHash);
  const resetError = () => setError('');
  const enterTeacher = async () => { const normalizedUsername = username.trim(); const normalizedSecret = secret.trim(); if (normalizedUsername.length < 2) { setError('教師帳號至少需要 2 個字元。'); return; } if (normalizedSecret.length < 4) { setError('教師密碼至少需要 4 個字元。'); return; } const hash = await hashSecret(normalizedSecret); if (firstTeacherLogin) { updateData({ ...data, teacherUsername: normalizedUsername, teacherPassword: '', teacherPasswordHash: hash }); onEnter('teacher', remember); return; } const usernameMatches = (data.teacherUsername || 'teacher').toLowerCase() === normalizedUsername.toLowerCase(); if (usernameMatches && ((data.teacherPasswordHash && hash === data.teacherPasswordHash) || (!data.teacherPasswordHash && normalizedSecret === data.teacherPassword))) { if (!data.teacherPasswordHash || !data.teacherUsername) updateData({ ...data, teacherUsername: data.teacherUsername || normalizedUsername, teacherPassword: '', teacherPasswordHash: hash }); onEnter('teacher', remember); return; } setError('教師帳號或密碼不正確。'); };
  const enterFamily = async () => { if (!data.inviteCode || !data.students.length) { setError('目前還沒有可用的班級邀請碼。'); return; } if (invite.trim().toUpperCase() !== data.inviteCode.toUpperCase()) { setError('邀請碼不正確，請向教師確認。'); return; } if (familyAccountReady) { updateData({ ...data, linkedChild: data.linkedChild || data.students[0].number }); onEnter('family', remember); return; } const normalizedUsername = familyUsername.trim(); const normalizedSecret = secret.trim(); if (normalizedUsername.length < 2) { setError('請設定家長帳號，至少 2 個字元。'); return; } if (normalizedSecret.length < 4) { setError('家長密碼至少需要 4 個字元。'); return; } const hash = await hashSecret(normalizedSecret); updateData({ ...data, familyUsername: normalizedUsername, familyPasswordHash: hash, linkedChild: data.linkedChild || data.students[0].number }); onEnter('family', remember); };
  const enterFamilyAccount = async () => { if (!familyAccountReady) { setError('尚未建立家長帳號，請先用邀請碼完成首次連結。'); return; } const normalizedSecret = secret.trim(); const hash = await hashSecret(normalizedSecret); if (familyUsername.trim().toLowerCase() === data.familyUsername.toLowerCase() && hash === data.familyPasswordHash) { updateData({ ...data, linkedChild: data.linkedChild || data.students[0]?.number || null }); onEnter('family', remember); return; } setError('家長帳號或密碼不正確。'); };
  const isFamily = role === 'family';
  const submit = role === 'teacher' ? () => void enterTeacher() : authMode === 'invite' ? () => void enterFamily() : () => void enterFamilyAccount();
  return <main className="login-page"><section className="login-panel"><Logo /><div className="login-copy"><span>安全登入</span><h1>{role === 'teacher' ? (firstTeacherLogin ? '設定教師帳號' : '教師登入') : '家長登入'}</h1><p>{role === 'teacher' ? '只有通過教師帳號與密碼，才能進入班級管理與作業資料。' : '學生不建立登入帳號；家長可首次用邀請碼建立自己的帳密。'}</p></div><div className="login-choice"><button className={cn(role === 'teacher' && 'selected')} onClick={() => { setRole('teacher'); setError(''); }}><Users size={19} /><div><strong>教師登入</strong><small>班級與作業管理</small></div>{role === 'teacher' && <Check size={16} />}</button><button className={cn(role === 'family' && 'selected')} onClick={() => { setRole('family'); setError(''); }}><HomeIcon size={19} /><div><strong>家長登入</strong><small>聯絡簿與孩子作業</small></div>{role === 'family' && <Check size={16} />}</button></div>{isFamily && <div className="login-mode"><button className={cn(authMode === 'invite' && 'active')} onClick={() => { setAuthMode('invite'); resetError(); }}>邀請碼首次連結</button><button className={cn(authMode === 'account' && 'active')} onClick={() => { setAuthMode('account'); resetError(); }}>帳號密碼登入</button></div>}{role === 'teacher' ? <><label className="login-field">教師帳號<input value={username} onChange={(event) => { setUsername(event.target.value); resetError(); }} placeholder="例如 teacher" autoComplete="username" /></label><label className="login-field">{firstTeacherLogin ? '建立教師密碼' : '教師密碼'}<input type="password" autoComplete={firstTeacherLogin ? 'new-password' : 'current-password'} value={secret} onChange={(event) => { setSecret(event.target.value); resetError(); }} placeholder="至少 4 個字元" onKeyDown={(event) => { if (event.key === 'Enter') void enterTeacher(); }} /></label></> : authMode === 'invite' ? <><label className="login-field">班級邀請碼<input value={invite} onChange={(event) => { setInvite(event.target.value); resetError(); }} placeholder="例如 CLASS-7F2P9" /></label>{!familyAccountReady && <><label className="login-field">建立家長帳號<input value={familyUsername} onChange={(event) => { setFamilyUsername(event.target.value); resetError(); }} placeholder="例如 wang.family" autoComplete="username" /></label><label className="login-field">建立家長密碼<input type="password" autoComplete="new-password" value={secret} onChange={(event) => { setSecret(event.target.value); resetError(); }} placeholder="至少 4 個字元" onKeyDown={(event) => { if (event.key === 'Enter') void enterFamily(); }} /></label></>}</> : <><label className="login-field">家長帳號<input value={familyUsername} onChange={(event) => { setFamilyUsername(event.target.value); resetError(); }} placeholder="輸入家長帳號" autoComplete="username" /></label><label className="login-field">家長密碼<input type="password" autoComplete="current-password" value={secret} onChange={(event) => { setSecret(event.target.value); resetError(); }} placeholder="輸入家長密碼" onKeyDown={(event) => { if (event.key === 'Enter') void enterFamilyAccount(); }} /></label></>}<label className="remember-login"><input type="checkbox" checked={remember} onChange={(event) => setRemember(event.target.checked)} /> 在這台裝置保持登入</label>{error && <p className="login-error">{error}</p>}<Button className="full-button" onClick={submit}>{role === 'teacher' ? (firstTeacherLogin ? '建立並進入教師端' : '登入教師端') : authMode === 'invite' ? (familyAccountReady ? '用邀請碼登入家長端' : '建立家長帳號並登入') : '登入家長端'} <ArrowRight size={16} /></Button><small className="login-note">學生只在教師開啟的大螢幕點選座號，不會取得教師權限。</small></section></main>;
}

function Topbar({ role, onRole, onLogout }: { role: Role; onRole: (role: Role) => void; onLogout: () => void }) {
  return <header className="simple-topbar"><Logo /><div className="top-role">{role === 'teacher' && <><button className="active">教師端</button><button onClick={() => onRole('screen')}>大螢幕</button></>}{role === 'family' && <button className="active">家長端</button>}{role === 'screen' && <button className="active">大螢幕</button>}</div><div className="top-user"><span className="user-avatar">{role === 'family' ? '家' : '師'}</span><span>{role === 'family' ? '家長帳號' : '教師帳號'}</span>{role !== 'screen' && <button aria-label="登出" onClick={onLogout}><LogOut size={15} /></button>}{role === 'screen' && <Button size="sm" variant="outline" onClick={() => onRole('teacher')}><X size={14} /> 離開</Button>}</div></header>;
}

function Sidebar({ role, teacherView, familyView, setTeacherView, setFamilyView, data }: { role: Role; teacherView: TeacherView; familyView: FamilyView; setTeacherView: (view: TeacherView) => void; setFamilyView: (view: FamilyView) => void; data: AppData }) {
  if (role === 'screen') return null;
  const teacherItems: Array<[TeacherView, string, ReactNode]> = [['home', '總覽', <ClipboardCheck size={17} key="home" />], ['journal', '聯絡簿', <BookOpen size={17} key="journal" />], ['homework', '作業', <CheckCircle2 size={17} key="homework" />], ['class', '班級', <Users size={17} key="class" />], ['tools', '教學工具', <Grid2X2 size={17} key="tools" />], ['settings', '設定', <Settings2 size={17} key="settings" />]];
  const familyItems: Array<[FamilyView, string, ReactNode]> = [['journal', '聯絡簿', <BookOpen size={17} key="journal" />], ['homework', '作業', <CheckCircle2 size={17} key="homework" />], ['calendar', '行事曆', <CalendarDays size={17} key="calendar" />], ['me', '我的', <Settings2 size={17} key="me" />]];
  return <aside className="simple-sidebar"><div className="sidebar-context"><span className="context-label">{role === 'teacher' ? '目前班級' : '已連結孩子'}</span><strong>{role === 'teacher' ? data.className || '尚未建立班級' : data.linkedChild ? data.students.find((student) => student.number === data.linkedChild)?.name || '孩子' : '尚未連結孩子'}</strong><small>{role === 'teacher' ? `${data.students.length} 位學生` : data.className || '輸入邀請碼即可開始'}</small></div><nav>{role === 'teacher' ? teacherItems.map(([id, label, icon]) => <button key={id} className={cn(teacherView === id && 'active')} onClick={() => setTeacherView(id)}>{icon}<span>{label}</span>{id === 'homework' && data.homeworks.length > 0 && <i>{data.homeworks.length}</i>}</button>) : familyItems.map(([id, label, icon]) => <button key={id} className={cn(familyView === id && 'active')} onClick={() => setFamilyView(id)}>{icon}<span>{label}</span></button>)}</nav><div className="sidebar-help"><Bell size={15} /><span>{role === 'teacher' ? '先建立班級，再開始發布內容。' : '聯絡簿由老師發布，家長可以回覆。'}</span></div></aside>;
}

function EmptyState({ icon, title, text, action }: { icon: ReactNode; title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{action}</div>; }

function TeacherHome({ data, updateData, go }: { data: AppData; updateData: (next: AppData) => void; go: (view: TeacherView) => void }) {
  const [className, setClassName] = useState(data.className); const [classError, setClassError] = useState('');
  const createClass = () => { const name = className.trim(); if (!name) { setClassError('請先輸入班級名稱。'); return; } setClassError(''); updateData({ ...data, className: name, inviteCode: data.inviteCode || 'CLASS-' + Math.random().toString(36).slice(2, 7).toUpperCase() }); };
  if (!data.className) return <div className="workspace"><div className="workspace-head"><div><span className="kicker">教師端・第一次使用</span><h1>先建立你的班級</h1><p>完成這一步後，就能新增學生、發布聯絡簿與管理作業。</p></div></div><section className="simple-card setup-card"><div className="step-number">1</div><div className="setup-copy"><h2>班級名稱</h2><p>例如：五年三班。這個名稱會顯示給家長。</p><div className="input-row"><input value={className} onChange={(event) => { setClassName(event.target.value); setClassError(''); }} placeholder="輸入班級名稱" /><Button onClick={createClass}>建立班級 <ArrowRight size={15} /></Button></div>{classError && <p className="form-error">{classError}</p>}</div></section></div>;
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">教師端・{today}</span><h1>{data.className} <span className="muted-title">工作區</span></h1><p>從這裡建立今天要讓家庭知道的內容。</p></div><Button onClick={() => go('journal')}><Plus size={16} /> 建立今日聯絡簿</Button></div><div className="quick-grid"><button onClick={() => go('class')}><span className="quick-icon peach"><Users size={19} /></span><strong>新增學生</strong><small>{data.students.length ? `${data.students.length} 位學生` : '目前還沒有學生'}</small></button><button onClick={() => go('journal')}><span className="quick-icon green"><BookOpen size={19} /></span><strong>發布聯絡簿</strong><small>{data.journals.filter((journal) => journal.date === today && journal.published).length ? '今日已有發布內容' : '今天尚未發布'}</small></button><button onClick={() => go('homework')}><span className="quick-icon blue"><CheckCircle2 size={19} /></span><strong>新增作業</strong><small>{data.homeworks.length ? `${data.homeworks.length} 項作業` : '目前還沒有作業'}</small></button></div><div className="two-column"><section className="simple-card"><div className="card-heading"><div><span className="kicker">今天</span><h2>聯絡簿狀態</h2></div><Pill tone={data.journals.some((journal) => journal.date === today && journal.published) ? 'green' : 'gray'}>{data.journals.some((journal) => journal.date === today && journal.published) ? '已發布' : '尚未發布'}</Pill></div>{data.journals.length ? <div className="compact-list">{data.journals.slice().reverse().slice(0, 3).map((journal) => <div key={journal.id}><span>{journal.date}</span><strong>{journal.homework || journal.notice || '聯絡簿內容'}</strong><Pill tone={journal.published ? 'green' : 'gray'}>{journal.published ? '已發布' : '草稿'}</Pill></div>)}</div> : <EmptyState icon={<BookOpen size={20} />} title="還沒有聯絡簿" text="新增一篇，讓家長知道今天的作業與提醒。" action={<Button variant="outline" size="sm" onClick={() => go('journal')}>新增聯絡簿</Button>} />}</section><section className="simple-card"><div className="card-heading"><div><span className="kicker">班級</span><h2>作業追蹤</h2></div><Button variant="ghost" size="sm" onClick={() => go('homework')}>查看 <ArrowRight size={14} /></Button></div>{data.homeworks.length ? <div className="compact-list">{data.homeworks.slice().reverse().slice(0, 4).map((work) => <div key={work.id}><span className="subject-tag">{work.subject || '作業'}</span><strong>{work.title}</strong><small>{new Set([...work.screenReported, ...work.familyDone]).size} 人有回報</small></div>)}</div> : <EmptyState icon={<CheckCircle2 size={20} />} title="還沒有作業" text="建立作業後，學生就能在教室大螢幕登記。" action={<Button variant="outline" size="sm" onClick={() => go('homework')}>新增作業</Button>} />}</section></div></div>;
}

function JournalEditor({ data, updateData, selectedDate, existing }: { data: AppData; updateData: (next: AppData) => void; selectedDate: string; existing?: Journal }) {
  const [homework, setHomework] = useState(existing?.homework || '');
  const [bring, setBring] = useState(existing?.bring || '');
  const [notice, setNotice] = useState(existing?.notice || '');
  const save = (published: boolean) => { const journal: Journal = { id: existing?.id || makeId('journal'), date: selectedDate, homework: homework.trim(), bring: bring.trim(), notice: notice.trim(), published, readBy: existing?.readBy || false, reply: existing?.reply || '', readByStudents: existing?.readByStudents || [], replies: existing?.replies || {} }; updateData({ ...data, journals: [...data.journals.filter((item) => item.date !== selectedDate), journal] }); };
  const replies = existing?.replies ? Object.entries(existing.replies).filter(([, value]) => value.trim()) : [];
  return <><section className="simple-card form-card"><label>今天的作業<textarea value={homework} onChange={(event) => setHomework(event.target.value)} placeholder="例如：數學課本第 42–43 頁；國語朗讀第 3 課。" /></label><label>明天要帶什麼<textarea value={bring} onChange={(event) => setBring(event.target.value)} placeholder="例如：自然觀察紀錄單、水壺。" /></label><label>班級提醒<textarea value={notice} onChange={(event) => setNotice(event.target.value)} placeholder="例如：週三進行校外教學行前說明。" /></label><div className="form-actions"><span>內容會顯示在家長端</span><div><Button variant="outline" onClick={() => save(false)}><Save size={14} /> 儲存草稿</Button><Button onClick={() => save(true)}>發布給家長 <ExternalLink size={15} /></Button></div></div></section>{replies.length > 0 && <section className="simple-card reply-preview"><span className="kicker">家長回覆</span>{replies.map(([number, value]) => <p className="reply-line" key={number}><strong>{data.students.find((student) => String(student.number) === number)?.name || `${number} 號家長`}</strong>{value}</p>)}</section>}</>;
}

function TeacherJournal({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [selectedDate, setSelectedDate] = useState(today);
  const existing = data.journals.find((journal) => journal.date === selectedDate);
  const history = data.journals.slice().sort((a, b) => b.date.localeCompare(a.date));
  return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">聯絡簿</span><h1>{selectedDate === today ? '今天要讓家庭知道什麼？' : `${selectedDate} 聯絡簿`}</h1><p>可回看過往日期，儲存草稿後再發布。</p></div><Pill tone={existing?.published ? 'green' : 'gray'}>{existing?.published ? '已發布' : '草稿'}</Pill></div><section className="simple-card journal-date-picker"><label>編輯日期<input type="date" value={selectedDate} onChange={(event) => setSelectedDate(event.target.value || today)} /></label><Button variant="outline" size="sm" onClick={() => setSelectedDate(today)}>回到今天</Button></section><JournalEditor key={selectedDate} data={data} updateData={updateData} selectedDate={selectedDate} existing={existing} />{history.length > 0 && <section className="simple-card journal-history"><div className="card-heading"><div><span className="kicker">紀錄</span><h2>過往聯絡簿</h2></div><Pill tone="gray">{history.length} 篇</Pill></div>{history.slice(0, 10).map((item) => <button key={item.id} className={cn(item.id === existing?.id && 'active')} onClick={() => setSelectedDate(item.date)}><span>{item.date}</span><strong>{item.homework || item.notice || item.bring || '聯絡簿內容'}</strong><Pill tone={item.published ? 'green' : 'gray'}>{item.published ? '已發布' : '草稿'}</Pill><ArrowRight size={14} /></button>)}</section>}</div>;
}

function TeacherHomework({ data, updateData, openScreen }: { data: AppData; updateData: (next: AppData) => void; openScreen: (homeworkId: string) => void }) {
  const [subject, setSubject] = useState(''); const [title, setTitle] = useState(''); const [due, setDue] = useState(''); const [formError, setFormError] = useState(''); const [query, setQuery] = useState(''); const [statusFilter, setStatusFilter] = useState<'全部' | '未完成' | '待核對' | '已完成'>('全部');
  const add = () => { if (!title.trim()) { setFormError('請輸入作業名稱。'); return; } setFormError(''); const homework: Homework = { id: makeId('homework'), subject: subject.trim() || '作業', title: title.trim(), due: due.trim() || '未設定', screenReported: [], familyDone: [], teacherConfirmed: [] }; updateData({ ...data, homeworks: [...data.homeworks, homework] }); setSubject(''); setTitle(''); setDue(''); };
  const remove = (work: Homework) => { if (!window.confirm(`確定刪除「${work.title}」？相關登記也會一併移除。`)) return; updateData({ ...data, homeworks: data.homeworks.filter((item) => item.id !== work.id) }); };
  const confirm = (work: Homework, studentNumber: number) => { const reported = work.screenReported.includes(studentNumber) || work.familyDone.includes(studentNumber); if (!reported && !work.teacherConfirmed.includes(studentNumber)) return; const next = work.teacherConfirmed.includes(studentNumber) ? work.teacherConfirmed.filter((number) => number !== studentNumber) : [...work.teacherConfirmed, studentNumber]; updateData({ ...data, homeworks: data.homeworks.map((item) => item.id === work.id ? { ...item, teacherConfirmed: next } : item) }); };
  const confirmAll = (work: Homework) => { const reported = [...new Set([...work.screenReported, ...work.familyDone])]; updateData({ ...data, homeworks: data.homeworks.map((item) => item.id === work.id ? { ...item, teacherConfirmed: reported } : item) }); };
  const exportReport = () => { const rows = [['作業', '科目', '截止日', '座號', '學生', '狀態']]; data.homeworks.forEach((work) => data.students.forEach((student) => rows.push([work.title, work.subject, work.due, String(student.number), student.name, statusLabel(work, student.number)]))); downloadFile('班級作業統計.csv', rows.map((row) => row.map(csvEscape).join(',')).join('\n'), 'text/csv;charset=utf-8'); };
  const visible = data.homeworks.slice().reverse().filter((work) => { const matchesQuery = `${work.subject} ${work.title}`.toLowerCase().includes(query.trim().toLowerCase()); if (!matchesQuery) return false; if (statusFilter === '全部') return true; const registered = new Set([...work.screenReported, ...work.familyDone]).size; if (statusFilter === '未完成') return registered < data.students.length; if (statusFilter === '待核對') return registered > work.teacherConfirmed.length; return data.students.length > 0 && registered > 0 && work.teacherConfirmed.length >= data.students.length; });
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">作業</span><h1>建立與核對</h1><p>學生在大螢幕登記，家長也能回報，教師在這裡確認。</p></div><Button variant="outline" onClick={exportReport} disabled={!data.homeworks.length}><Download size={15} /> 匯出統計</Button></div><section className="simple-card add-form"><div className="field"><label>科目<input value={subject} onChange={(event) => setSubject(event.target.value)} placeholder="數學" /></label><label>作業名稱<input value={title} onChange={(event) => { setTitle(event.target.value); setFormError(''); }} placeholder="第 6 單元練習" /></label><label>截止日<input type="date" value={due} onChange={(event) => setDue(event.target.value)} /></label><Button onClick={add}><Plus size={15} /> 新增</Button></div>{formError && <p className="form-error">{formError}</p>}</section>{data.homeworks.length > 0 && <section className="simple-card homework-filters"><label className="search-field"><Search size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="搜尋科目或作業名稱" /></label><select aria-label="篩選作業狀態" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as typeof statusFilter)}><option>全部</option><option>未完成</option><option>待核對</option><option>已完成</option></select><span className="filter-count">顯示 {visible.length} / {data.homeworks.length}</span></section>}{data.homeworks.length === 0 ? <section className="simple-card"><EmptyState icon={<CheckCircle2 size={20} />} title="還沒有作業" text="建立第一項作業後，就能開啟教室大螢幕。" /></section> : visible.length === 0 ? <section className="simple-card"><EmptyState icon={<Search size={20} />} title="找不到符合的作業" text="換個關鍵字或清除狀態篩選。" /></section> : <div className="work-list">{visible.map((work) => { const registered = new Set([...work.screenReported, ...work.familyDone]); const canConfirmAll = registered.size > 0; return <section className="simple-card work-card" key={work.id}><div className="work-head"><div><span className="subject-tag">{work.subject}</span><h2>{work.title}</h2><small>截止 {work.due}</small></div><div className="work-head-actions"><Button onClick={() => openScreen(work.id)}><Grid2X2 size={15} /> 開啟大螢幕</Button><Button variant="outline" size="sm" disabled={!canConfirmAll} onClick={() => confirmAll(work)}><ShieldCheck size={14} /> 全部核對</Button><Button variant="ghost" size="sm" aria-label={`刪除${work.title}`} onClick={() => remove(work)}><Trash2 size={14} /> 刪除</Button></div></div><div className="work-summary"><span>已登記 <strong>{registered.size}</strong> / {data.students.length}</span><span>教師確認 <strong>{work.teacherConfirmed.length}</strong></span><span>{work.teacherConfirmed.length === data.students.length && data.students.length > 0 ? '全班完成' : registered.size > work.teacherConfirmed.length ? '有待核對' : '等待登記'}</span></div>{data.students.length ? <div className="student-check-grid">{data.students.map((student) => <button key={student.number} className={cn(work.teacherConfirmed.includes(student.number) && 'confirmed')} disabled={!registered.has(student.number) && !work.teacherConfirmed.includes(student.number)} onClick={() => confirm(work, student.number)}><strong>{String(student.number).padStart(2, '0')}</strong><span>{student.name}</span><small>{statusLabel(work, student.number)}</small></button>)}</div> : <p className="inline-note">請先到「班級」新增學生，才能追蹤繳交狀態。</p>}</section>; })}</div>}</div>;
}

function TeacherClass({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [number, setNumber] = useState(data.students.length ? String(Math.max(...data.students.map((student) => student.number)) + 1) : '1'); const [name, setName] = useState(''); const [bulk, setBulk] = useState(''); const [formError, setFormError] = useState(''); const [copied, setCopied] = useState(false);
  const add = () => { const parsed = Number(number); if (!name.trim()) { setFormError('請輸入學生姓名。'); return; } if (!Number.isInteger(parsed) || parsed < 1 || parsed > 999) { setFormError('座號請輸入 1 到 999 的整數。'); return; } if (data.students.some((student) => student.number === parsed)) { setFormError('這個座號已經存在。'); return; } setFormError(''); updateData({ ...data, students: [...data.students, { number: parsed, name: name.trim() }].sort((a, b) => a.number - b.number), inviteCode: data.inviteCode || 'CLASS-' + Math.random().toString(36).slice(2, 7).toUpperCase() }); setName(''); setNumber(String(parsed + 1)); };
  const bulkAdd = () => { const rows = bulk.split(/\r?\n/).map((line) => line.trim()).filter(Boolean); const additions: Student[] = []; for (const row of rows) { const [numberText, ...nameParts] = row.split(/[,，\t]/); const parsed = Number(numberText?.trim()); const studentName = nameParts.join(' ').trim(); if (!Number.isInteger(parsed) || parsed < 1 || parsed > 999 || !studentName || data.students.some((student) => student.number === parsed) || additions.some((student) => student.number === parsed)) { setFormError(`無法匯入「${row}」，格式請用：座號,姓名，且座號不可重複。`); return; } additions.push({ number: parsed, name: studentName }); } if (!additions.length) { setFormError('請先貼上至少一行學生資料。'); return; } setFormError(''); updateData({ ...data, students: [...data.students, ...additions].sort((a, b) => a.number - b.number), inviteCode: data.inviteCode || 'CLASS-' + Math.random().toString(36).slice(2, 7).toUpperCase() }); setBulk(''); };
  const copy = async () => { if (!data.inviteCode) return; try { await navigator.clipboard?.writeText(data.inviteCode); setCopied(true); window.setTimeout(() => setCopied(false), 1800); } catch { setFormError('瀏覽器未允許複製，請手動選取邀請碼。'); } };
  const exportStudents = () => downloadFile('班級名單.csv', [['座號', '學生姓名'], ...data.students.map((student) => [String(student.number), student.name])].map((row) => row.map(csvEscape).join(',')).join('\n'), 'text/csv;charset=utf-8');
  const renameStudent = (student: Student) => { const nextName = window.prompt(`修改 ${String(student.number).padStart(2, '0')} 號姓名`, student.name)?.trim(); if (!nextName || nextName === student.name) return; updateData({ ...data, students: data.students.map((item) => item.number === student.number ? { ...item, name: nextName } : item) }); };
  const removeStudent = (numberToRemove: number, studentName: string) => { if (!window.confirm(`確定移除 ${String(numberToRemove).padStart(2, '0')} 號 ${studentName}？`)) return; updateData({ ...data, students: data.students.filter((student) => student.number !== numberToRemove), linkedChild: data.linkedChild === numberToRemove ? null : data.linkedChild, homeworks: data.homeworks.map((work) => ({ ...work, screenReported: work.screenReported.filter((number) => number !== numberToRemove), familyDone: work.familyDone.filter((number) => number !== numberToRemove), teacherConfirmed: work.teacherConfirmed.filter((number) => number !== numberToRemove) })), journals: data.journals.map((journal) => ({ ...journal, readByStudents: journal.readByStudents?.filter((number) => number !== numberToRemove), replies: Object.fromEntries(Object.entries(journal.replies || {}).filter(([key]) => key !== String(numberToRemove))) })) }); };
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">班級</span><h1>學生與家長連結</h1><p>學生只有座號資料，家長用邀請碼連結孩子。</p></div><Button variant="outline" onClick={exportStudents} disabled={!data.students.length}><Download size={15} /> 匯出名單</Button></div><section className="simple-card class-code-card"><div><span className="kicker">家長邀請碼</span><strong>{data.inviteCode || '新增第一位學生後產生'}</strong></div><Button variant="outline" size="sm" disabled={!data.inviteCode} onClick={() => void copy()}><Copy size={14} /> {copied ? '已複製' : '複製'}</Button></section><section className="simple-card add-student-card"><div className="field"><label>座號<input inputMode="numeric" value={number} onChange={(event) => { setNumber(event.target.value); setFormError(''); }} /></label><label>學生姓名<input value={name} onChange={(event) => { setName(event.target.value); setFormError(''); }} placeholder="輸入姓名" /></label><Button onClick={add}><Plus size={15} /> 新增學生</Button></div></section><section className="simple-card bulk-student-card"><div className="card-heading"><div><span className="kicker">快速匯入</span><h2>一次貼上名單</h2></div><FileText size={18} /></div><p>每行一位，格式：座號,姓名。也支援從試算表直接貼上。</p><textarea value={bulk} onChange={(event) => { setBulk(event.target.value); setFormError(''); }} placeholder={'1,王小明\n2,林小華'} /><Button variant="outline" onClick={bulkAdd}><Upload size={15} /> 匯入名單</Button>{formError && <p className="form-error">{formError}</p>}</section><section className="simple-card"><div className="card-heading"><div><span className="kicker">班級名單</span><h2>{data.students.length} 位學生</h2></div></div>{data.students.length === 0 ? <EmptyState icon={<Users size={20} />} title="還沒有學生" text="先新增學生，接著把邀請碼給家長。" /> : <div className="student-list">{data.students.map((student) => <div key={student.number}><span className="number-badge">{String(student.number).padStart(2, '0')}</span><strong>{student.name}</strong><span>家長用班級邀請碼連結</span><Button variant="ghost" size="sm" onClick={() => renameStudent(student)}>修改</Button><Button variant="ghost" size="sm" onClick={() => removeStudent(student.number, student.name)}><X size={13} /> 移除</Button></div>)}</div>}</section></div>;
}

function TeacherTools({ data }: { data: AppData }) {
  const [seconds, setSeconds] = useState(15 * 60); const [running, setRunning] = useState(false); const [drawn, setDrawn] = useState<Student | null>(null); const [groupCount, setGroupCount] = useState(4); const [groups, setGroups] = useState<Student[][]>([]);
  useEffect(() => { if (!running) return; const timer = window.setInterval(() => setSeconds((value) => { if (value <= 1) { setRunning(false); return 0; } return value - 1; }), 1000); return () => window.clearInterval(timer); }, [running]);
  const draw = () => { if (!data.students.length) return; setDrawn(data.students[Math.floor(Math.random() * data.students.length)]); };
  const makeGroups = () => { const shuffled = [...data.students].sort(() => Math.random() - .5); const next = Array.from({ length: Math.max(1, Math.min(groupCount, shuffled.length || 1)) }, () => [] as Student[]); shuffled.forEach((student, index) => next[index % next.length].push(student)); setGroups(next); };
  const time = `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`;
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">教學工具</span><h1>課堂小工具</h1><p>把計時、抽籤與分組集中在同一頁。</p></div></div><div className="tool-grid"><section className="simple-card tool-panel"><div className="tool-panel-head"><Clock3 size={18} /><h2>課堂計時器</h2></div><div className="timer-value">{time}</div><div className="timer-presets"><button onClick={() => setSeconds(5 * 60)}>05:00</button><button onClick={() => setSeconds(15 * 60)}>15:00</button><button onClick={() => setSeconds(25 * 60)}>25:00</button></div><div className="tool-actions"><Button onClick={() => setRunning((value) => !value)}>{running ? '暫停' : seconds === 0 ? '重新開始' : '開始'}</Button><Button variant="outline" onClick={() => { setRunning(false); setSeconds(15 * 60); }}><RotateCcw size={14} /> 重設</Button></div></section><section className="simple-card tool-panel"><div className="tool-panel-head"><Dices size={18} /><h2>隨機抽籤</h2></div><p className="tool-description">從目前班級名單抽出一位學生。</p><div className="draw-result">{drawn ? <><strong>{String(drawn.number).padStart(2, '0')}・{drawn.name}</strong><small>可以再抽一次</small></> : <><strong>尚未抽籤</strong><small>{data.students.length ? `目前有 ${data.students.length} 位學生` : '先到班級新增學生'}</small></>}</div><Button onClick={draw} disabled={!data.students.length}><Dices size={15} /> 抽一位</Button></section><section className="simple-card tool-panel"><div className="tool-panel-head"><Users size={18} /><h2>快速分組</h2></div><div className="group-control"><label>組數<input type="number" min="1" max={Math.max(1, data.students.length)} value={groupCount} onChange={(event) => setGroupCount(Number(event.target.value) || 1)} /></label><Button onClick={makeGroups} disabled={!data.students.length}>產生分組</Button></div>{groups.length ? <div className="group-result">{groups.map((group, index) => <div key={index}><strong>第 {index + 1} 組</strong><span>{group.map((student) => `${student.number} ${student.name}`).join('、')}</span></div>)}</div> : <p className="tool-description">依組數平均分配目前名單。</p>}</section></div></div>;
}

function TeacherSettings({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [eventTitle, setEventTitle] = useState(''); const [eventDate, setEventDate] = useState(''); const [eventType, setEventType] = useState<CalendarEvent['type']>('提醒'); const [eventError, setEventError] = useState(''); const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [accountMessage, setAccountMessage] = useState(''); const [fileMessage, setFileMessage] = useState(''); const fileRef = useRef<HTMLInputElement>(null);
  const addEvent = () => { if (!eventTitle.trim() || !eventDate.trim()) { setEventError('請填寫日期與事件名稱。'); return; } setEventError(''); updateData({ ...data, events: [...data.events, { id: makeId('event'), title: eventTitle.trim(), date: eventDate.trim(), type: eventType }] }); setEventTitle(''); setEventDate(''); };
  const removeEvent = (event: CalendarEvent) => { if (!window.confirm(`確定移除「${event.title}」？`)) return; updateData({ ...data, events: data.events.filter((item) => item.id !== event.id) }); };
  const changePassword = async () => { if (newPassword.trim().length < 4) { setAccountMessage('新密碼至少需要 4 個字元。'); return; } const currentHash = await hashSecret(currentPassword.trim()); if (data.teacherPasswordHash && currentHash !== data.teacherPasswordHash) { setAccountMessage('目前密碼不正確。'); return; } const nextHash = await hashSecret(newPassword.trim()); updateData({ ...data, teacherPassword: '', teacherPasswordHash: nextHash }); setCurrentPassword(''); setNewPassword(''); setAccountMessage('教師密碼已更新。'); };
  const exportBackup = () => downloadFile(`班級小本本備份-${getToday()}.json`, JSON.stringify(data, null, 2));
  const importBackup = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; file.text().then((text) => { try { const parsed = JSON.parse(text) as Partial<AppData>; if (!Array.isArray(parsed.students) || !Array.isArray(parsed.journals) || !Array.isArray(parsed.homeworks) || !Array.isArray(parsed.events)) throw new Error('format'); updateData({ ...emptyData, ...parsed }); setFileMessage('備份已匯入。'); } catch { setFileMessage('檔案格式不正確，請選擇班級小本本匯出的 JSON。'); } }).catch(() => setFileMessage('無法讀取備份檔案。')).finally(() => { if (fileRef.current) fileRef.current.value = ''; }); };
  const resetWorkspace = () => { if (!window.confirm('確定清除班級、作業、聯絡簿與行事曆？此動作無法復原。')) return; updateData({ ...emptyData, teacherUsername: data.teacherUsername, teacherPasswordHash: data.teacherPasswordHash }); setAccountMessage('工作區已清除，請重新建立班級。'); };
  return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">設定</span><h1>班級偏好</h1><p>帳號、資料備份與介面設定都集中在這裡。</p></div></div><section className="simple-card settings-panel"><div className="settings-row"><div><strong><Palette size={16} /> 主題色</strong><small>調整工作區的重點色。</small></div><div className="theme-picks"><button aria-label="珊瑚色" className={cn('theme-pick coral', data.theme === 'coral' && 'active')} onClick={() => updateData({ ...data, theme: 'coral' })} /><button aria-label="藍色" className={cn('theme-pick blue', data.theme === 'blue' && 'active')} onClick={() => updateData({ ...data, theme: 'blue' })} /><button aria-label="綠色" className={cn('theme-pick mint', data.theme === 'mint' && 'active')} onClick={() => updateData({ ...data, theme: 'mint' })} /></div></div><div className="settings-row"><div><strong><Grid2X2 size={16} /> 網格背景</strong><small>保留淡淡的筆記本網格。</small></div><button aria-label="切換網格背景" aria-pressed={data.grid} className={cn('toggle', data.grid && 'on')} onClick={() => updateData({ ...data, grid: !data.grid })}><span /></button></div></section><section className="simple-card account-panel"><div className="card-heading"><div><span className="kicker">帳號操作</span><h2><LockKeyhole size={17} /> 更新教師密碼</h2></div><ShieldCheck size={18} /></div><div className="field"><label>目前密碼<input type="password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} /></label><label>新密碼<input type="password" value={newPassword} onChange={(event) => setNewPassword(event.target.value)} placeholder="至少 4 個字元" /></label><Button onClick={() => void changePassword()}><Save size={14} /> 更新密碼</Button></div>{accountMessage && <p className="form-message">{accountMessage}</p>}</section><section className="simple-card account-panel"><div className="card-heading"><div><span className="kicker">資料管理</span><h2>備份與還原</h2></div><FileText size={18} /></div><p className="inline-note">匯出檔案可以保存班級名單、聯絡簿、作業與行事曆，換裝置時再匯入。</p><div className="settings-actions"><Button variant="outline" onClick={exportBackup}><Download size={14} /> 匯出備份</Button><Button variant="outline" onClick={() => fileRef.current?.click()}><Upload size={14} /> 匯入備份</Button><input ref={fileRef} type="file" accept="application/json,.json" hidden onChange={importBackup} /></div>{fileMessage && <p className="form-message">{fileMessage}</p>}</section><section className="simple-card event-panel"><div className="card-heading"><div><span className="kicker">行事曆</span><h2>新增班級事件</h2></div></div><div className="field"><label>日期<input type="date" value={eventDate} onChange={(event) => { setEventDate(event.target.value); setEventError(''); }} /></label><label>事件名稱<input value={eventTitle} onChange={(event) => { setEventTitle(event.target.value); setEventError(''); }} placeholder="校外教學" /></label><label>類型<select value={eventType} onChange={(event) => setEventType(event.target.value as CalendarEvent['type'])}><option>提醒</option><option>活動</option><option>考試</option></select></label><Button onClick={addEvent}><Plus size={15} /> 新增</Button></div>{eventError && <p className="form-error">{eventError}</p>}{data.events.length ? <div className="event-list">{data.events.slice().sort((a, b) => a.date.localeCompare(b.date)).map((event) => <div key={event.id}><span>{event.date}</span><strong>{event.title}</strong><Pill tone="blue">{event.type}</Pill><Button variant="ghost" size="sm" aria-label={`移除${event.title}`} onClick={() => removeEvent(event)}><X size={13} /> 移除</Button></div>)}</div> : <p className="inline-note">尚未建立班級事件。</p>}</section><section className="simple-card danger-panel"><div><strong><Trash2 size={16} /> 清除工作區</strong><small>保留教師帳號，刪除班級內所有資料。</small></div><Button variant="outline" onClick={resetWorkspace}>清除資料</Button></section></div>;
}

function FamilyCalendar({ data }: { data: AppData }) {
  const events = [...data.events, ...data.homeworks.map((work) => ({ id: work.id, date: work.due, title: `${work.subject}・${work.title}`, type: '提醒' as const }))];
  return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">家長端</span><h1>行事曆</h1><p>查看班級活動與孩子作業期限。</p></div></div><section className="simple-card calendar-panel">{events.length ? <div className="event-list large">{events.sort((a, b) => a.date.localeCompare(b.date)).map((event) => <div key={event.id}><span>{event.date}</span><strong>{event.title}</strong><Pill tone={event.type === '考試' ? 'orange' : 'blue'}>{event.type}</Pill></div>)}</div> : <EmptyState icon={<CalendarDays size={20} />} title="還沒有行事曆內容" text="老師新增活動或作業期限後，會顯示在這裡。" />}</section></div>;
}

function FamilyView({ view, data, updateData }: { view: FamilyView; data: AppData; updateData: (next: AppData) => void }) {
  const [code, setCode] = useState(''); const [reply, setReply] = useState(''); const [selectedJournalId, setSelectedJournalId] = useState<string | null>(null); const [linkError, setLinkError] = useState(''); const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [accountMessage, setAccountMessage] = useState('');
  const child = data.students.find((student) => student.number === data.linkedChild);
  const link = () => { if (code.trim().toUpperCase() === data.inviteCode.toUpperCase() && data.students.length) { setLinkError(''); updateData({ ...data, linkedChild: data.students[0].number }); } else setLinkError('邀請碼不正確，請向老師確認。'); };
  if (!data.linkedChild || !child) return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">家長端</span><h1>先連結孩子</h1><p>請向老師索取班級邀請碼，輸入後就能看到聯絡簿。</p></div></div><section className="simple-card link-card"><label>班級邀請碼<input value={code} onChange={(event) => { setCode(event.target.value); setLinkError(''); }} placeholder="例如 CLASS-7F2P9" /></label><Button onClick={link} disabled={!data.inviteCode}>連結孩子 <ArrowRight size={15} /></Button>{linkError && <p className="form-error">{linkError}</p>}{!data.className && <p className="inline-note">老師尚未建立班級，請稍後再試。</p>}{data.className && !data.students.length && <p className="inline-note">老師已建立 {data.className}，但還沒有學生名單。</p>}</section></div>;
  const publishedJournals = data.journals.filter((item) => item.published).slice().sort((a, b) => b.date.localeCompare(a.date));
  const journal = publishedJournals.find((item) => item.id === selectedJournalId) || publishedJournals[0];
  const journalIsRead = journal ? journalReadBy(journal, child.number) : false;
  const childReply = journal ? journalReply(journal, child.number) : '';
  const setJournal = (next: Journal) => updateData({ ...data, journals: data.journals.map((item) => item.id === next.id ? next : item) });
  if (view === 'homework') return <div className="workspace"><div className="workspace-head"><div><span className="kicker">家長端・{child.name}</span><h1>作業</h1><p>孩子可以在教室登記，家長也能回報已完成。</p></div></div><div className="family-work-list">{data.homeworks.length ? data.homeworks.map((work) => { const done = work.familyDone.includes(child.number); return <section className="simple-card family-work" key={work.id}><div><span className="subject-tag">{work.subject}</span><h2>{work.title}</h2><p>截止 {work.due}</p><Pill tone={work.teacherConfirmed.includes(child.number) ? 'green' : done ? 'orange' : 'gray'}>{statusLabel(work, child.number)}</Pill></div><Button variant={done ? 'outline' : 'default'} onClick={() => updateData({ ...data, homeworks: data.homeworks.map((item) => item.id === work.id ? { ...item, familyDone: done ? item.familyDone.filter((number) => number !== child.number) : [...item.familyDone, child.number] } : item) })}>{done ? <><Check size={15} /> 已完成</> : '我做完了'}</Button></section>; }) : <section className="simple-card"><EmptyState icon={<CheckCircle2 size={20} />} title="老師還沒有發布作業" text="有新的作業時，會出現在這裡。" /></section>}</div></div>;
  if (view === 'calendar') return <FamilyCalendar data={data} />;
  if (view === 'me') { const changePassword = async () => { if (newPassword.trim().length < 4) { setAccountMessage('新密碼至少需要 4 個字元。'); return; } const currentHash = await hashSecret(currentPassword.trim()); if (data.familyPasswordHash && currentHash !== data.familyPasswordHash) { setAccountMessage('目前密碼不正確。'); return; } const nextHash = await hashSecret(newPassword.trim()); updateData({ ...data, familyPasswordHash: nextHash }); setCurrentPassword(''); setNewPassword(''); setAccountMessage('家長密碼已更新。'); }; return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">我的帳號</span><h1>家庭設定</h1><p>目前連結：{child.name}・{data.className}</p></div></div><section className="simple-card"><div className="setting-line"><span>家庭邀請碼</span><strong>{data.inviteCode}</strong></div><div className="setting-line"><span>切換孩子</span><select aria-label="切換孩子" value={String(child.number)} onChange={(event) => updateData({ ...data, linkedChild: Number(event.target.value) })}>{data.students.map((student) => <option key={student.number} value={student.number}>{String(student.number).padStart(2, '0')} 號・{student.name}</option>)}</select></div><div className="setting-line"><span>資料保存</span><strong>本機瀏覽器</strong></div></section><section className="simple-card account-panel"><div className="card-heading"><div><span className="kicker">帳號操作</span><h2><LockKeyhole size={17} /> 更新家長密碼</h2></div></div><div className="field"><label>目前密碼<input type="password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} /></label><label>新密碼<input type="password" value={newPassword} onChange={(event) => setNewPassword(event.target.value)} placeholder="至少 4 個字元" /></label><Button onClick={() => void changePassword()}><Save size={14} /> 更新密碼</Button></div>{accountMessage && <p className="form-message">{accountMessage}</p>}</section></div>; }
  return <div className="workspace family-workspace"><div className="workspace-head"><div><span className="kicker">家長端・{child.name}</span><h1>聯絡簿</h1><p>{data.className}・座號 {String(child.number).padStart(2, '0')}</p></div><Pill tone={journalIsRead ? 'green' : 'orange'}>{journalIsRead ? '已確認閱讀' : '待確認閱讀'}</Pill></div>{journal ? <><section className="simple-card family-journal"><div className="journal-date">{journal.date}</div>{journal.homework && <div><h3><ClipboardCheck size={16} /> 今天的作業</h3><p>{journal.homework}</p></div>}{journal.bring && <div><h3><CalendarDays size={16} /> 明天要帶</h3><p>{journal.bring}</p></div>}{journal.notice && <div><h3><Bell size={16} /> 班級提醒</h3><p>{journal.notice}</p></div>}<div className="family-actions">{journalIsRead ? <span className="confirmed-line"><CheckCircle2 size={16} /> 已在本機記錄閱讀</span> : <Button onClick={() => setJournal({ ...journal, readBy: true, readByStudents: [...(journal.readByStudents || []), child.number] })}><Check size={15} /> 我已閱讀</Button>}</div></section><section className="simple-card reply-card"><h2><MessageCircle size={17} /> 回覆老師</h2>{childReply && <p className="sent-reply">上次回覆：{childReply}</p>}<textarea value={reply} onChange={(event) => setReply(event.target.value)} placeholder="例如：明天會帶齊觀察單，謝謝老師。" /><Button size="sm" disabled={!reply.trim()} onClick={() => { const nextReply = reply.trim(); setJournal({ ...journal, reply: nextReply, replies: { ...journal.replies, [String(child.number)]: nextReply } }); setReply(''); }}><Send size={14} /> 送出回覆</Button></section>{publishedJournals.length > 1 && <section className="simple-card journal-history"><div className="card-heading"><div><span className="kicker">紀錄</span><h2>過往聯絡簿</h2></div></div>{publishedJournals.filter((item) => item.id !== journal.id).slice(0, 5).map((item) => <button key={item.id} onClick={() => setSelectedJournalId(item.id)}><span>{item.date}</span><strong>{item.homework || item.notice || item.bring || '聯絡簿內容'}</strong><ArrowRight size={14} /></button>)}</section>}</> : <section className="simple-card"><EmptyState icon={<BookOpen size={20} />} title="老師還沒有發布今天的聯絡簿" text="發布後會在這裡看到作業、攜帶物品與班級提醒。" /></section>}</div>;
}

function Screen({ data, homeworkId, setRole, updateData }: { data: AppData; homeworkId: string | null; setRole: (role: Role) => void; updateData: (next: AppData) => void }) {
  const work = data.homeworks.find((item) => item.id === homeworkId) || data.homeworks[0];
  if (!work) return <div className="screen-empty"><h1>還沒有可登記的作業</h1><p>請先回到教師端建立作業。</p><Button onClick={() => setRole('teacher')}>回到教師端</Button></div>;
  return <main className="screen-view"><div className="screen-heading"><div><span className="kicker">{data.className}・教室大螢幕</span><h1>{work.subject}・{work.title}</h1><p>請點選自己的座號；完成後由教師核對。</p></div><div className="screen-count"><strong>{new Set([...work.screenReported, ...work.familyDone]).size}</strong><span>/ {data.students.length} 已登記</span></div></div><section className="screen-card"><div className="screen-instruction"><strong>點一下座號</strong><span>再點一次可以撤銷登記</span></div>{data.students.length ? <div className="screen-grid">{data.students.map((student) => { const selected = work.screenReported.includes(student.number); return <button key={student.number} className={cn(selected && 'selected')} onClick={() => updateData({ ...data, homeworks: data.homeworks.map((item) => item.id === work.id ? { ...item, screenReported: selected ? item.screenReported.filter((number) => number !== student.number) : [...item.screenReported, student.number] } : item) })}><strong>{String(student.number).padStart(2, '0')}</strong><span>{student.name}</span>{selected && <CheckCircle2 size={18} />}</button>; })}</div> : <EmptyState icon={<Users size={20} />} title="還沒有學生名單" text="請先回教師端新增學生。" />}<div className="screen-foot"><span>只顯示座號與登記狀態</span><Button variant="outline" onClick={() => setRole('teacher')}><X size={14} /> 結束</Button></div></section></main>;
}

export default function Home() {
  const [hydrated, setHydrated] = useState(false); const [loggedIn, setLoggedIn] = useState(false); const [role, setRole] = useState<Role>('teacher'); const [teacherView, setTeacherView] = useState<TeacherView>('home'); const [familyView, setFamilyView] = useState<FamilyView>('journal'); const [screenHomeworkId, setScreenHomeworkId] = useState<string | null>(null); const [data, setData] = useState<AppData>(emptyData);
  useEffect(() => { const timer = window.setTimeout(() => { try { const stored = window.localStorage.getItem(storageKey); if (stored) setData({ ...emptyData, ...JSON.parse(stored) }); const session = JSON.parse(window.localStorage.getItem(sessionKey) || 'null') as { role?: Role } | null; if (session?.role === 'teacher' || session?.role === 'family') { setRole(session.role); setLoggedIn(true); } } catch { /* empty state is safe */ } setHydrated(true); }, 0); return () => window.clearTimeout(timer); }, []);
  useEffect(() => { if (hydrated) window.localStorage.setItem(storageKey, JSON.stringify(data)); }, [data, hydrated]);
  const updateData = (next: AppData) => setData(next);
  if (!hydrated) return <main className="loading-page"><Logo /><span>載入工作區…</span></main>;
  if (!loggedIn) return <Login data={data} updateData={updateData} onEnter={(nextRole, remember) => { setRole(nextRole); setLoggedIn(true); if (remember) window.localStorage.setItem(sessionKey, JSON.stringify({ role: nextRole })); }} />;
  const logout = () => { window.localStorage.removeItem(sessionKey); setLoggedIn(false); setRole('teacher'); };
  if (role === 'screen') return <><Topbar role={role} onRole={setRole} onLogout={logout} /><Screen data={data} homeworkId={screenHomeworkId} setRole={setRole} updateData={updateData} /></>;
  return <div className={cn('simple-app', `theme-${data.theme}`, data.grid ? 'with-grid' : 'no-grid')}><Topbar role={role} onRole={(nextRole) => { setRole(nextRole); }} onLogout={logout} /><Sidebar role={role} teacherView={teacherView} familyView={familyView} setTeacherView={setTeacherView} setFamilyView={setFamilyView} data={data} />{role === 'teacher' ? teacherView === 'home' ? <TeacherHome data={data} updateData={updateData} go={setTeacherView} /> : teacherView === 'journal' ? <TeacherJournal data={data} updateData={updateData} /> : teacherView === 'homework' ? <TeacherHomework data={data} updateData={updateData} openScreen={(id) => { setScreenHomeworkId(id); setRole('screen'); }} /> : teacherView === 'class' ? <TeacherClass data={data} updateData={updateData} /> : teacherView === 'tools' ? <TeacherTools data={data} /> : <TeacherSettings data={data} updateData={updateData} /> : <FamilyView view={familyView} data={data} updateData={updateData} />}</div>;
}
